use std::process::Command;

fn validate_pdf(file_path: &str) -> bool {
    let output = Command::new("file")
        .arg("--mime-type")
        .arg(file_path)
        .output()
        .expect("Failed to execute command");

    let mime_type = String::from_utf8_lossy(&output.stdout);
    mime_type.contains("application/pdf")
}

fn main() {
    let test_file = "example.pdf";
    assert!(validate_pdf(test_file), "File is not a valid PDF");
}

